const input = $('Execute Sub Workflow Trigger').first().json;
const execResult = items[0].json;
const exitCode = execResult.exitCode || 0;
const stdout = execResult.stdout || '';

let parsed = {};
try { parsed = JSON.parse(stdout); } catch(e) { parsed = { raw: stdout }; }

return [{json: {
  ...input,
  color_grade_exit_code: exitCode,
  color_grade_result: parsed
}}];

const input = $('Parse Color Grade Result').first().json;
const execResult = items[0].json;
const exitCode = execResult.exitCode || 0;
const stdout = execResult.stdout || '';

let parsed = {};
try { parsed = JSON.parse(stdout); } catch(e) { parsed = { raw: stdout }; }

return [{json: {
  ...input,
  delivery_exit_code: exitCode,
  delivery_result: parsed,
  status: exitCode === 0 ? 'complete' : 'failed'
}}];
